#include <iostream>
using namespace std;

long long fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);
}

int main() {
    int n;
    cin >> n;
    cout << fact(n) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int findMax(int a[], int l, int r) {
    if (l == r) return a[l];
    int mid = (l + r) / 2;
    int leftMax = findMax(a, l, mid);
    int rightMax = findMax(a, mid + 1, r);
    return leftMax > rightMax ? leftMax : rightMax;
}

int main() {
    int a[] = {3, 7, 2, 9, 1, 5};
    cout << findMax(a, 0, 5) << endl;
    return 0;
}

#include <iostream>
using namespace std;

long long fastPow(long long a, long long b, long long mod) {
    long long result = 1;
    a %= mod;
    while (b > 0) {
        if (b & 1) result = result * a % mod;
        a = a * a % mod;
        b >>= 1;
    }
    return result;
}

int main() {
    cout << fastPow(2, 10, 1000000007) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int n;
    cin >> n;
    int l = 1, r = n;
