#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, q;
    cin >> n >> q;
    vector<pair<int,int>> queries(q);
    for (int i = 0; i < q; i++) {
        cin >> queries[i].first >> queries[i].second;
    }
    sort(queries.begin(), queries.end());
    for (auto& p : queries) {
        cout << p.first << " " << p.second << endl;
    }
    return 0;
}

#include <iostream>
#include <set>
using namespace std;

int main() {
    set<int> small = {1, 2, 3};
    set<int> large = {10, 20, 30, 40, 50};
    if (small.size() > large.size()) swap(small, large);
    for (int x : small) {
        large.insert(x);
    }
    for (int x : large) cout << x << " ";
    cout << endl;
    return 0;
}

